@dataclass
class ScoredWallet:
    """A Polymarket wallet scored by historical BTC 15m trading performance."""
    address: str
    username: str
    total_trades: int
    wins: int
    losses: int
    win_rate: float
    total_pnl_usd: float
    avg_trade_size: float
    markets_traded: int
    last_scored_at: float
    up_trades: int = 0
    up_wins: int = 0
    down_trades: int = 0
    down_wins: int = 0
    hold_rate: float = 1.0  # 1.0 = never sells before expiry, 0.0 = sells everything
    tier: str = "elite"  # "elite" (high WR) or "algo" (high volume + 75%+ WR)


@dataclass
class SmartFlowState:
    """Real-time smart money flow on the active Polymarket BTC 15m market."""
    # WR-weighted volume allocation
    up_weighted_volume: float = 0.0     # WR-weighted $ going to Up
    down_weighted_volume: float = 0.0   # WR-weighted $ going to Down
    total_weighted_volume: float = 0.0  # Total WR-weighted $

    # Raw counts
    up_wallets: int = 0                 # Unique smart wallets betting Up
    down_wallets: int = 0               # Unique smart wallets betting Down
    total_smart_trades: int = 0         # Total smart trades in window

    # Derived
    flow_direction: str = ""            # "up" or "down" (majority weighted side)
    flow_conviction: float = 0.0        # 0.0-1.0, fraction on majority side
    avg_smart_wr: float = 0.0           # Average WR of active smart wallets

    # Elite wallet tracking — wallets with WR >= ELITE_WR_THRESHOLD
    elite_up_wallets: list = field(default_factory=list)    # [(addr, wr, wtd_vol), ...]
    elite_down_wallets: list = field(default_factory=list)  # [(addr, wr, wtd_vol), ...]

    # Wallet VWAP — volume-weighted average entry price on Polymarket (in cents)
    # Tells us what fair value smart money sees for the winning side
    smart_vwap_cents: float = 50.0

    updated_at: float = 0.0

    @property
    def is_stale(self) -> bool:
        return (time.time() - self.updated_at) > FLOW_STALE_S if self.updated_at > 0 else True


@dataclass
class KalshiTapeState:
    """Real-time Kalshi anonymous tape analysis for KXBTC15M."""
    # Taker flow in rolling window
    yes_taker_volume: int = 0           # Total YES taker contracts
    no_taker_volume: int = 0            # Total NO taker contracts
    total_taker_volume: int = 0

    # Price
    mid_price_cents: float = 50.0       # Current mid-price
    last_trade_price_cents: float = 50.0
    vwap_cents: float = 50.0            # Volume-weighted avg price

    # Derived
    taker_imbalance: float = 0.0        # -1.0 (all NO) to +1.0 (all YES)
    large_trade_bias: float = 0.0       # Bias from trades > 10 contracts

    updated_at: float = 0.0

    @property
    def is_stale(self) -> bool:
        """True if tape data hasn't been updated recently (poll errors/timeouts)."""
        if self.updated_at == 0.0:
            return True
        return (time.time() - self.updated_at) > TAPE_STALE_S

    @property
    def implied_up_prob(self) -> float:
        """Kalshi's current implied probability that BTC goes up."""
        return self.mid_price_cents / 100.0


@dataclass
class PriceActionReading:
    """Snapshot of contract price action + trade flow for entry decisions."""
    mid_move: int = 0           # Current mid - open mid (cents, + = YES)
    mid_rate: float = 0.0       # Cents per second (recent trajectory)
    flow_dir: str = ""          # "up", "down", "" from Kalshi WS trade flow
    flow_strength: float = 0.0  # 0.0-1.0 from TradeFlowTracker
    taker_imbalance: float = 0.0  # -1.0 (NO) to +1.0 (YES)
    votes_up: int = 0           # How many voters say YES
    votes_down: int = 0         # How many voters say NO
    phase: int = 0              # 1=early, 2=confirmed, 3=chase
    window_age_s: float = 0.0   # Seconds since window opened


@dataclass
class CrossVenueSignal:
    """Trading signal from smart flow vs Kalshi divergence."""
    kalshi_side: str                    # "yes" or "no"

    # Smart flow
    smart_flow_direction: str           # "up" or "down"
    smart_flow_conviction: float        # 0.0-1.0
    smart_wallets_active: int
    smart_avg_wr: float
    smart_weighted_volume: float

    # Kalshi tape
    kalshi_mid_cents: float
    kalshi_taker_imbalance: float

    # Divergence = the edge
    divergence: float                   # Smart conviction - Kalshi alignment
    implied_edge_cents: float           # Estimated cents of mispricing

    # Tier
    signal_tier: str = "PRIMARY"       # "PRIMARY" or "MIMIC"

    generated_at: float = 0.0


@dataclass
class EngineState:
    """Published state for logging/UI."""
    scored_wallets: int = 0
    active_poly_market: str = ""
    active_kalshi_ticker: str = ""
    smart_flow: Optional[SmartFlowState] = None
    kalshi_tape: Optional[KalshiTapeState] = None
    last_signal: Optional[CrossVenueSignal] = None
    trades_this_window: int = 0
    total_trades: int = 0
    updated_at: float = 0.0


# ─────────────────────────────────────────────
# Engine
# ─────────────────────────────────────────────

class PolymarketCopyEngine:
    """Cross-venue flow analysis engine: Polymarket smart money → Kalshi KXBTC15M.

    Identifies high-WR Polymarket wallets, tracks their real-time BTC 15m
    volume allocation, and enters on Kalshi when smart flow diverges from
    Kalshi's current pricing.
    """

    # 2026-05-02 Phase 0.1.2: per-window ticker lock persistence path.
    _SESSION_LOCK_PATH = os.path.join("data", "session_state.json")
    _SESSION_LOCK_MAX_AGE_S = 900  # one Kalshi 15-min window

    # 2026-05-06: separate persistence for DIRECTION-active tickers.
    # Without this, an engine restart while a DIRECTION position is open
    # loses the in-memory _direction_active_tickers set, and SYNC_RECLAIM
    # adopts the orphan via the legacy TA_FORCED reclaim path. Same
    # 15-min auto-expiry as the session lock — a ticker that's been
    # idle that long has either settled or been abandoned.
    _DIRECTION_ACTIVE_PATH = os.path.join("data", "direction_active.json")
    _DIRECTION_ACTIVE_MAX_AGE_S = 900

    def _load_session_lock(self) -> set:
        """Load `_entered_tickers_this_window` from disk if recent.

        Lock auto-expires after 15 minutes (one window). If the saved
        timestamp is older, return an empty set — the window has rotated
        and the lock no longer applies.
        """
        try:
            import json
            if not os.path.exists(self._SESSION_LOCK_PATH):
                return set()
            with open(self._SESSION_LOCK_PATH, "r", encoding="utf-8") as f:
                data = json.load(f)
            saved_at = float(data.get("saved_at_ms", 0)) / 1000.0
            if not saved_at or (time.time() - saved_at) > self._SESSION_LOCK_MAX_AGE_S:
                return set()
            tickers = data.get("tickers", []) or []
            restored = set(t for t in tickers if isinstance(t, str) and t)
            if restored:
                logger.warning(
                    "SESSION-LOCK: restored %d ticker(s) from disk: %s "
                    "(age=%.0fs)",
                    len(restored), ", ".join(sorted(restored))[:200],
                    time.time() - saved_at,
                )
            return restored
        except Exception as _e:
            logger.warning("SESSION-LOCK load failed: %s", _e)
            return set()

    def _persist_session_lock(self) -> None:
        """Write `_entered_tickers_this_window` to disk with timestamp.

        Must be called every time a ticker is added so a restart 1ms
        later restores the same lock state.
        """
        try:
            import json
            os.makedirs(os.path.dirname(self._SESSION_LOCK_PATH), exist_ok=True)
            payload = {
                "saved_at_ms": int(time.time() * 1000),
                "tickers": sorted(self._entered_tickers_this_window),
            }
            with open(self._SESSION_LOCK_PATH, "w", encoding="utf-8") as f:
                json.dump(payload, f)
        except Exception as _e:
            logger.warning("SESSION-LOCK persist failed: %s", _e)

    def _add_session_lock(self, ticker: str) -> None:
        """Add a ticker to the window-lock set AND persist to disk."""
        try:
            self._entered_tickers_this_window.add(ticker)
            self._persist_session_lock()
        except Exception:
            pass

    def _load_direction_active(self) -> set:
        """Load `_direction_active_tickers` from disk if recent.
        Same auto-expiry semantics as `_load_session_lock`."""
        try:
            import json
            if not os.path.exists(self._DIRECTION_ACTIVE_PATH):
                return set()
            with open(self._DIRECTION_ACTIVE_PATH, "r", encoding="utf-8") as f:
                data = json.load(f)
            saved_at = float(data.get("saved_at_ms", 0)) / 1000.0
            if not saved_at or (time.time() - saved_at) > self._DIRECTION_ACTIVE_MAX_AGE_S:
                return set()
            tickers = data.get("tickers", []) or []
            restored = set(t for t in tickers if isinstance(t, str) and t)
            if restored:
                logger.warning(
                    "DIRECTION-ACTIVE: restored %d ticker(s) from disk: %s "
                    "(age=%.0fs) — SYNC_RECLAIM/ORPHAN_FLATTEN opt-out "
                    "preserved across restart",
                    len(restored), ", ".join(sorted(restored))[:200],
                    time.time() - saved_at,
                )
            return restored
        except Exception as _e:
            logger.warning("DIRECTION-ACTIVE load failed: %s", _e)
            return set()

    def _persist_direction_active(self) -> None:
        """Write `_direction_active_tickers` to disk with timestamp.

        Must be called whenever the set changes so a restart preserves
        the SYNC_RECLAIM/ORPHAN_FLATTEN opt-out for open DIRECTION
        positions. Today (2026-05-06 20:34-37 PT) we caught a regression:
        engine restart at 20:36 lost the in-memory set, SYNC_RECONCILE
        adopted the still-open 9ct YES position as TA_FORCED, PROTECTIVE
        placed a sell that filled at 43c (luckily profitable +$0.60).
        Without this persistence, a reversed scenario would lock in a loss.
        """
        try:
            import json
            os.makedirs(os.path.dirname(self._DIRECTION_ACTIVE_PATH), exist_ok=True)
            payload = {
                "saved_at_ms": int(time.time() * 1000),
                "tickers": sorted(self._direction_active_tickers),
            }
            with open(self._DIRECTION_ACTIVE_PATH, "w", encoding="utf-8") as f:
                json.dump(payload, f)
        except Exception as _e:
            logger.warning("DIRECTION-ACTIVE persist failed: %s", _e)

    def _add_direction_active(self, ticker: str) -> None:
        """Add ticker to direction-active set AND persist to disk."""
        try:
            self._direction_active_tickers.add(ticker)
            self._persist_direction_active()
        except Exception:
            pass

    def _remove_session_lock(self, ticker: str) -> None:
        """Remove a ticker from the window-lock set AND persist to disk.

        Used when a place_order call FAILS (e.g., post_only_cross from
        Kalshi rejecting a maker-bid that crossed the spread). The lock
        was set pre-await for race-prevention; if the order never
        landed at Kalshi, we should not block subsequent retries on
        the same ticker. Distinct from NOFILL (where the order DID land
        but didn't fill — that case keeps the lock per "one attempt
        per session" rule).
        """
        try:
            self._entered_tickers_this_window.discard(ticker)
            self._persist_session_lock()
        except Exception:
            pass

    def __init__(
        self,
        kalshi_client,
        copy_engine_ref: dict,
        position_mgr=None,
        signal_logger=None,
        whale_ref: Optional[dict] = None,
    ) -> None:
        self._client = kalshi_client
        # ── Engine order-ID tracking (Claude 2026-04-28) ─────────────────
        # Set used by the SYNC RESIDUAL FLATTEN gates AND the manual_fills
        # poller to distinguish engine-placed orders from user manual
        # trades. Populated:
        #   1. At startup by _load_engine_order_ids() (from kalshi_trades)
        #   2. Live by wrapping place_order — every successful return adds
        #      its order_id to this set
        # Live wrap: monkey-patch self._client.place_order to capture.
        self._engine_order_ids: set = set()
        try:
            _orig_place_order = self._client.place_order
            async def _tracked_place_order(*args, **kwargs):
                _o = await _orig_place_order(*args, **kwargs)
                try:
                    _oid = getattr(_o, "order_id", None) if _o else None
                    if _oid:
                        self._engine_order_ids.add(str(_oid))
                except Exception:
                    pass
                return _o
            self._client.place_order = _tracked_place_order
        except Exception:
            # If wrapping fails (e.g. PaperTrader missing place_order at this
            # init point), fall back to no live tracking — startup load and
            # explicit calls to _track_engine_order still work.
            pass
        self._ref = copy_engine_ref
        self._position_mgr = position_mgr
        self._signal_logger = signal_logger
        self._whale_ref = whale_ref  # {"state": WhaleFlowState} from WhaleMonitor

        # Scored wallets: address → ScoredWallet
        self._wallets: dict[str, ScoredWallet] = {}
        self._wallet_addresses: set[str] = set()

        # Active Polymarket market
        self._active_poly_market: Optional[dict] = None
        self._active_poly_condition_id: str = ""
        self._seen_poly_tx: set[str] = set()

        # Smart flow: rolling window of (timestamp, wallet, direction, wr_weighted_volume)
        self._smart_trades: deque = deque()
        self._smart_flow = SmartFlowState()

        # Kalshi tape: rolling window of (timestamp, taker_side, count, price_cents)
        self._kalshi_trades: deque = deque()
        self._kalshi_tape = KalshiTapeState()
        self._kalshi_seen_ids: set = set()  # Dedup insertion into _kalshi_trades
        self._last_kalshi_trade_id: str = ""
        self._current_kalshi_ticker: str = ""

        # Execution state
        self._trades_this_window: int = 0
        self._losses_this_window: int = 0   # 2026-04-14: kill bad sessions fast
        self._window_locked: bool = False
        self._total_trades: int = 0
        self._last_entry_time: float = 0.0
        self._open_position: Optional[dict] = None
        self._last_stop_ticker: str = ""       # Ticker of last stopped-out position
        self._pending_ladder_orders: list = []  # Track all unfilled ladder order IDs for ghost prevention
        self._instant_buy_fired_this_window: bool = False
        self._last_stop_time: float = 0.0      # Time of last stop-loss exit
        self._closed_tickers: set = set()      # Tickers where we sold/closed — sync must skip these
        # 2026-05-03 PT 20:30 — LOSS-STREAK COOLDOWN (B3) state.
        # Tracks consecutive BB_PURE losses for the cooldown gate.
        # Approximates loss/win at close time using entry_cents vs current
        # bid (precise P&L attribution deferred to B2). Counter increments
        # on close-with-loss, resets on close-with-win, decays after
        # BB_PURE_LOSS_STREAK_RELEASE_WINDOWS windows w/o a fire.
        self._bb_pure_loss_streak: int = 0
        self._bb_pure_streak_last_fire_window_id: int = -1
        self._bb_pure_streak_decay_counter: int = 0
        # 2026-04-22: Belt-and-suspenders per-window entry guard.
        # Independent of `_trades_this_window` counter (which has had reset
        # bugs in the past). Any ticker we've entered is permanently locked
        # out for the remainder of its 15-min life. Cleared on new-window.
        # 2026-05-02 Phase 0.1.2: persist across engine restarts. Live test
        # 01:35 PT showed the engine restart at 01:33 cleared this set,
        # allowing a 3rd entry on the same locked ticker. State now persists
        # to data/session_state.json with a saved_at timestamp; on startup
        # we restore tickers if the file is < 15 min old (one window).
        self._entered_tickers_this_window: set = self._load_session_lock()

        # 2026-05-06: DIRECTION-active ticker registry. Populated when a
        # DIRECTION strategy fill lands; consulted by SYNC RECLAIM and
        # ORPHAN-FLATTEN loops so they don't adopt/flatten DIRECTION
        # positions (which are managed via hold-to-settlement, not via
        # the legacy _open_position machinery's exit paths).
        # Persisted to disk (same 15-min expiry as session lock) so the
        # opt-out survives engine restart while a DIRECTION position is
        # open. Without persistence, restart caused SYNC_RECONCILE to
        # adopt the orphan as TA_FORCED (caught 2026-05-06 20:36 PT;
        # trade got lucky at +$0.60 but reversed scenario would lock loss).
        self._direction_active_tickers: set = self._load_direction_active()

        # 2026-05-06 evening: DIRECTION-pending registry. With the switch
        # from IOC taker (immediate-or-cancel at the ask) to post_only
        # maker (resting bid at ask-1), placed orders sit on Kalshi until
        # the market comes back to our price OR our timeout fires. The
        # registry tracks {ticker: {oid, place_ts, side, count, px}} so
        # the next eval cycle can poll status, transition to FILL on
        # fill, or cancel + clear on timeout.
        # Why the switch: 0/62 fill rate at 17:51 PT showed Kalshi 15m
        # ask depth is consistently < 5-10ct of size at the snapshot
        # time, so IOC always returns filled_count=0. Resting maker bids
        # at ask-1 trade less frequently but actually fill when they do.
        self._direction_pending_orders: dict = {}

        # 2026-05-06 night: separate position state for DIRECTION strategy.
        # Today's session caught 4 distinct legacy code paths each
        # adopting/managing DIRECTION fills via _open_position:
        #   - SYNC RECLAIM (yesterday) → -$7.53
        #   - VWAP_EXIT (yesterday) → -$0.85 + $5.60 forfeited
        #   - DOMINANT_UPGRADE (today) → 7ct → 14ct doubled bet, settled NO
        # The pattern: anything that gates on `_open_position is not None`
        # sees DIRECTION fills and applies BB_PURE/TA_FORCED-style exit
        # logic.
        # Architecture fix: DIRECTION fills now set self._direction_position
        # instead of self._open_position. The 20+ legacy exit paths gate
        # on _open_position; they auto-skip when it stays None. Only
        # SYNC_RECLAIM and ORPHAN_FLATTEN scan Kalshi truth independent
        # of _open_position — both already consult
        # _direction_active_tickers and skip DIRECTION tickers.
        # Net: DIRECTION attack surface reduced from ~20 paths to 0
        # (SYNC_RECLAIM and ORPHAN_FLATTEN both opted out).
        self._direction_position: dict | None = None

        # 2026-04-29 GHOST-bug fix #5: track per-ticker order PLACEMENT
        # timestamps. _entered_tickers_this_window only fills AFTER fill
        # confirmation reaches the engine, so when a maker order fills on
        # Kalshi but the WS fill event is delayed/missed, the reconciler
        # would fall to GHOST IGNORED. Stamping at place_order (BEFORE fill)
        # gives RECLAIM a way to claim the position on its own. Map of
        # {ticker: placement_ts}; entries older than 60s are ignored by
        # the consumer logic in the SYNC RECONCILE block.
        self._recent_placement_tickers: dict = {}
        # 2026-05-01: parallel store keyed on ticker for BB_PURE-specific
        # placement context. RECLAIM uses this to reconstruct a BB_PURE
        # position correctly (with strategy_name + fair_yes_cents) when
        # an order NOFILLs synchronously but cache catches up showing the
        # position later. Without this, RECLAIM resets strategy to
        # TA_FORCED_SIGNAL and the BB_PURE-aware TP/protective targets
        # are never used. {ticker: {ts, side, entry_cents,
        # fair_yes_cents, edge_pp}}
        self._recent_bb_pure_placements: dict = {}
        # 2026-05-01: count of BB_PURE FIREs in the current window. Reset
        # on new window. Capped by BB_PURE_MAX_FIRES_PER_WINDOW so the
        # engine can't third-trade itself into gambling territory.
        self._bb_pure_fires_this_window: int = 0
        # 2026-05-07 OVERHAUL Phase 1: universal safety counters.
        # _window_committed_cents tracks total dollars committed in the
        # current window across ALL tiers (DIRECTION/BB_PURE/PENNY). Each
        # successful fill increments by filled_count × entry_px. Reset on
        # window flip alongside _bb_pure_fires_this_window.
        # _window_entry_count tracks fill-events in the current window
        # across all tiers — enforces MAX_ENTRIES_PER_WINDOW.
        # _direction_halt_log_ts rate-limits the noisy DAILY-LOSS-HALT
        # log (Phase 2D).
        self._window_committed_cents: int = 0
        self._window_entry_count: int = 0
        self._direction_halt_log_ts: float = 0.0
        # _direction_last_nofill_ask_c[ticker] = ask_cents at the last
        # NOFILL on that ticker. Used by Phase 2A: a re-attempt must
        # show the ask has moved by ≥ DIRECTION_NOFILL_REQUIRE_ASK_DELTA_C
        # cents from this stamped value (in addition to the 30s
        # cooldown).
        self._direction_last_nofill_ask_c: dict = {}
        # 2026-05-01: shutdown flag. When True, paths that cancel resting
        # protective orders must NOT run. Live observed today on the 1200
        # ticker — after nssm stop, the engine kept running for ~3min and
        # cancelled the preflight TP, leaving the position naked. Position
        # settled to zero (-$211 loss). Setting this flag in a signal
        # handler at the top of run() and gating cancel paths on it.
        self._shutting_down: bool = False
        # 2026-05-01: every order_id the engine ever places. Used so fill
        # events from these orders are NEVER misattributed to "MANUAL
        # FILL RECORDED". Bounded growth: clean entries older than 24h.
        self._engine_placed_order_ids: dict = {}  # {order_id: placement_ts}
        # 2026-05-01: when True, _pre_expiry_consolidate has taken
        # exclusive ownership of the close. Other paths (protective
        # maintain, residual reconciler, post-close sweep) stand down.
        self._pre_expiry_consolidating: bool = False

        # 2026-05-08 MOMENTUM SCALP tier — dual-limit symmetric resting
        # buy pair at window open. Standalone state (not plumbed through
        # _direction_position or _open_position to keep the existing exit
        # cascade out of it; scalp manages its own trail). All fields are
        # reset in the window-change handler.
        # _scalp_evaluated: True after we've made the place-or-skip
        #   decision for the current window (idempotent placement guard).
        # _scalp_yes_order_id / _scalp_no_order_id: resting order IDs;
        #   None if not placed or already cancelled/filled.
        # _scalp_filled_side: "yes" / "no" / "both" / None
        # _scalp_ticker / _scalp_entry_price / _scalp_filled_count: fill ctx
        # _scalp_hwm_bid: highest contract bid (filled side) seen since fill
        # _scalp_fill_time: unix ts of fill (used by pre-expiry exit gate)
        # _scalp_exit_placed: True after we've fired a sell exit (stops the
        #   trail loop from re-firing).
        self._scalp_evaluated: bool = False
        self._scalp_yes_order_id: str | None = None
        self._scalp_no_order_id: str | None = None
        self._scalp_filled_side: str | None = None
        self._scalp_ticker: str = ""
        self._scalp_entry_price: int = 0
        self._scalp_filled_count: int = 0
        self._scalp_hwm_bid: int = 0
        self._scalp_btc_hwm: float = 0.0   # BTC price HWM for co-integrated trail
        self._scalp_btc_side: str = ""      # "yes" or "no" — which side BTC favors
        self._scalp_ladder_yes_ids: list = []
        self._scalp_ladder_no_ids: list = []
        self._scalp_last_ioc_ts: float = 0.0
        self._scalp_contracts_placed_window: int = 0
        self._scalp_cap_logged: bool = False
        self._scalp_fill_time: float = 0.0
        self._scalp_exit_placed: bool = False
        # exit order tracking — needed to cancel orphans on window flip
        self._scalp_exit_order_id: str | None = None
        self._scalp_exit_price_c: int = 0
        self._scalp_exit_fire_ts: float = 0.0
        # "both" tail bookkeeping
        self._scalp_yes_filled_count: int = 0
        self._scalp_no_filled_count: int = 0
        # Asymmetric re-entry after a TRAIL exit (2026-05-08). When True,
        # the next PHASE 1 placement uses dual-sided asymmetric pricing
        # rather than the normal single-sided BTC-aware bid. Set in
        # _scalp_fire_exit() only on reason=="TRAIL"; cleared after the
        # re-entry pair is placed (or on window flip).
        self._scalp_reentry_mode: bool = False
        self._scalp_prior_exit_side: str = ""
        # 2026-05-08 reversal-confidence scorer: snapshot of the INVERSE
        # side's best bid at fill time, used by _scalp_fire_exit() to
        # compute the velocity component of the reversal score.
        self._scalp_inv_bid_at_fill: int = 0
        # 2026-05-08 (evening) — INVERSE_REENTRY_ON_CLOSE: one-shot per
        # window. When a position closes (PROTECTIVE FLAT-CONFIRMED), if
        # this flag is False we place a +Nc IOC limit BUY on the opposite
        # side and set this flag to True so we don't fire repeatedly on
        # the multi-poll FLAT-CONFIRMED detection. Reset on window flip.
        self._inverse_reentry_done_this_window: bool = False

        # Daily loss tracking (circuit breaker)
        self._daily_pnl: float = 0.0           # Running P&L for current UTC day
        self._daily_pnl_date: str = ""         # UTC date string for reset detection
        self._daily_halted: bool = False        # True = halted for the day
        # 2026-04-23 (Codex P1): flag + DB reconciliation so the daily-loss
        # limit survives engine restarts. Previously every restart reset the
        # counter to 0, which let a service that had already lost its budget
        # resume trading. First call to _check_daily_loss_limit or
        # _record_daily_pnl on a new process reconciles from balance_snapshots.
        self._daily_pnl_reconciled: bool = False

        # Mimic tier state (tracked separately)
        self._mimic_trades_this_window: int = 0
        self._last_mimic_time: float = 0.0

        # Trend-follow tier state
        self._trend_trades_this_window: int = 0
        self._last_trend_time: float = 0.0

        self._window_start_time: float = 0.0

        # Previous window flow context (for conflict detection)
        self._prev_window_flow_direction: str = ""
        self._prev_window_flow_conviction: float = 0.0
        self._prev_window_flow_wallets: int = 0

        # Pre-open arb tracker
        self._poly_window_open_time: float = 0.0
        self._pre_open_arb_fired: bool = False

        # Open momentum tracker
        self._open_momentum_samples: list = []
        self._open_momentum_signal: Optional[dict] = None
        self._open_momentum_fired: bool = False
