        self._btc_last_price: Optional[float] = None     # Latest BTC price
        self._btc_last_check: float = 0.0
        # BTC momentum exit — rolling price buffer for RSI calc
        self._btc_price_buffer: list[float] = []  # Rolling BTC prices (one per update tick)
        self._btc_rsi: Optional[float] = None      # Current RSI value

        # TA-forced tier state
        self._ta_scorer = TAScorer()
        # surfer removed
        self._ta_trades_this_window: int = 0

        # MTF price feed + confluence scorer (initialized in run() when session is ready)
        self._price_feed: Optional[object] = None
        self._mtf: Optional[object] = None
        self._last_ta_time: float = 0.0
        self._last_ta_candle_fetch: float = 0.0
        # Anti-whipsaw: track TA direction consistency
        self._ta_prev_direction: str = ""       # Last TA direction seen
        self._ta_direction_since: float = 0.0   # When current direction started
        self._ta_last_trade_dir: str = ""       # Direction of last TA_FORCED trade
        self._ta_last_candle_ts: int = 0  # Timestamp of last processed candle
        self._ta_warmed_this_window: bool = False

        # Paper tracker state (VWAP pullback study)
        self._paper_tracker: dict = {}
